SELECT table_name, num_rows, last_analyzed
  FROM user_tables
 WHERE table_name = 'ORDERS';

SELECT table_name, num_rows, last_analyzed
  FROM user_tables
 WHERE table_name = 'ORDERS';

BEGIN
  DBMS_STATS.GATHER_TABLE_STATS(USER, 'ORDERS', cascade => TRUE);
END;
/

SELECT index_name, num_rows, distinct_keys, last_analyzed
  FROM user_indexes
 WHERE table_name = 'ORDERS'
 ORDER BY index_name;

UPDATE orders
   SET status = 'CANCELLED'
 WHERE order_id BETWEEN 801 AND 950;
COMMIT;

SELECT table_name, num_rows, last_analyzed, stale_stats
  FROM user_tab_statistics
 WHERE table_name = 'ORDERS';

SELECT table_name, inserts, updates, deletes, truncated
  FROM user_tab_modifications
 WHERE table_name = 'ORDERS';

EXEC DBMS_STATS.SET_TABLE_PREFS(USER, 'ORDERS', 'STALE_PERCENT', '5');

SELECT DBMS_STATS.GET_PREFS('STALE_PERCENT', USER, 'ORDERS') AS stale_pct
  FROM dual;
